    const set=push?unpack(nashFor().s[names.indexOf(p)]):topRange(om===1?raisePct(p):Math.min(95,raisePct(p)*om),w);
    const lr=limpRow(p),lm=pick({tight:1.1,loose:0.9,aggro:0.7}),limp=lr?topRange(lm===1?lr[1]:lr[1]*lm,w,set):new Set();
    SCN.push({id:'rfi-'+p,type:'rfi',hero:p,name:`${p} ${push?'shove':'open'}`,size:openSize(p),pct:pctOf(set),limpPct:pctOf(limp),limpable:!!lr,
      labels:{raise:push?'Shove':'Open',limp:'Limp',fold:'Fold'},sets:{raise:set,limp}});
