    const src=prof()==='bal'?(typeof PRO!=='undefined'&&PRO.v3):(typeof PROFD!=='undefined'&&PROFD.v3),fk=prof()==='bal'?`${N}-${D}`:`${PROFILE}-${N}-${D}`;
