  if(!parts.length) return `<b>${name}:</b> every one ${dflt==='check'?'checks':'folds'} here.`;
  return `<b>${name}:</b><br>${parts.join('<br>')}${anyRest?`<br><span class="tag ${tagCls(dflt)}">${s.labels[dflt]}</span>the rest`:''}`;
